import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export const safeStateFiles=['brand-brain.json','creator-assets.json','creator-runs.json','creator-analytics.json','creator-experiments.json','research-studio.json','opportunity-lab.json','product-studio.json','website-studio.json','campaigns.json','growth-queue.json','publish-jobs.json','plugin-registry-state.json','capacity-benchmark.json','platform-performance.json','creative-memory.json','campaign-learning.json','agent-handoffs.json','agent-marketplace.json'];
const forbidden=new Set(['google-oauth.json','owner-auth.json','integration-keys.json','workspace-members.json','owner-recovery.json']);
const cloneJson=file=>JSON.parse(fs.readFileSync(file,'utf8'));
const atomicJson=(file,value)=>{fs.mkdirSync(path.dirname(file),{recursive:true});const tmp=file+'.restore.tmp';fs.writeFileSync(tmp,JSON.stringify(value,null,2),{mode:0o600});fs.renameSync(tmp,file)};
export function buildBackupBundle(root){const state={},projects=[];for(const name of safeStateFiles){const file=path.join(root,name);if(fs.existsSync(file))state[name]=cloneJson(file)}const dir=path.join(root,'projects');if(fs.existsSync(dir))for(const id of fs.readdirSync(dir)){const file=path.join(dir,id,'project.json');if(fs.existsSync(file))projects.push({id,value:cloneJson(file)})}const payload={version:1,type:'creator-os-safe-backup',generatedAt:new Date().toISOString(),state,projects,excludedSensitive:[...forbidden],policy:{containsSecrets:false,mediaIncluded:false,restoreRequiresOwnerConfirmation:true}};payload.sha256=crypto.createHash('sha256').update(JSON.stringify({state,projects})).digest('hex');return payload}
export function validateBackupBundle(bundle){const issues=[];if(!bundle||bundle.version!==1||bundle.type!=='creator-os-safe-backup')issues.push('unsupported backup format');for(const name of Object.keys(bundle?.state||{})){if(forbidden.has(name)||!safeStateFiles.includes(name))issues.push(`unsafe state file: ${name}`)}for(const p of bundle?.projects||[]){if(!/^[a-zA-Z0-9-]{1,100}$/.test(String(p.id||''))||!p.value||typeof p.value!=='object')issues.push('invalid project entry')}const expected=crypto.createHash('sha256').update(JSON.stringify({state:bundle?.state||{},projects:bundle?.projects||[]})).digest('hex');if(bundle?.sha256!==expected)issues.push('backup checksum mismatch');return {ok:issues.length===0,issues,stateFiles:Object.keys(bundle?.state||{}).length,projects:Array.isArray(bundle?.projects)?bundle.projects.length:0}}
export function restoreBackupBundle(root,bundle,{confirm=''}={}){if(confirm!=='RESTORE SAFE STATE')throw Error('explicit restore confirmation is required');const valid=validateBackupBundle(bundle);if(!valid.ok)throw Error(valid.issues.join('; '));for(const [name,value] of Object.entries(bundle.state||{}))atomicJson(path.join(root,name),value);for(const item of bundle.projects||[])atomicJson(path.join(root,'projects',item.id,'project.json'),item.value);return {...valid,restoredAt:new Date().toISOString(),mediaRestored:false}}
